3	import (
4		"errors"
5		"fmt"
6		"os"
7		"syscall"
8	)
9	
10	// Record 是一次成功保存留下的、可供读取的记录。
11	type Record struct {
12		// ID 是记录标识。
13		ID RecordID
14		// Parent 是父记录标识。只有直接建立的槽首记录没有父记录（为空）；
15		// 分支槽的首条记录以来源槽记录为父，因此“槽首记录”并不等于
16		// “没有父记录”。
17		Parent RecordID
18		// SlotFirst 表示这是其所在槽的首条记录（直接建立的根记录，或从
19		// 其他槽分出的分支首记录）；它不代表 Parent 一定为空。
20		SlotFirst bool
21		// State 是记录保存时的完整世界数据（深拷贝，修改不影响存档）。
22		State State
23	}
24	
25	func acquireSharedLock(dir string) (*fileLock, error) {
26		path := dir + "/lock"
27		f, err := os.OpenFile(path, os.O_RDWR|os.O_CREATE, 0o600)
28		if err != nil {
29			return nil, err
30		}
31		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_SH); err != nil {
32			f.Close()
33			return nil, err
34		}
35		return &fileLock{f: f}, nil
36	}
37	
38	// loadAndVerifyLocked 读取记录文件，校验其文本编码（无效 UTF-8 字节与
39	// 不成对的 Unicode 代理项转义一律损坏）、同一对象内是否有重复名称、
40	// 记录格式版本、内容校验和（校验和已包含父记录关系）、父记录是否存在，
41	// 以及世界数据是否自洽。
42	//
43	// 文本编码检查在解析前按原始字节进行：encoding/json 会把无效字节与不成对
44	// 的代理项转义悄悄改写成替换字符“�”，若原记录本就含有合法的“�”，改写后
45	// 的文本甚至可能仍通过校验和检查，因此这类记录即使替换后的世界状态合法、
46	// 校验和匹配、规则版本也被接受，仍按损坏拒绝，绝不用替换字符补齐后交付。
47	//
48	// 同一对象内的名称出现第二次时整条记录视为损坏：encoding/json 对同名字段
49	// 静默采用后一个值，只要解码后的内容与校验和匹配，自相矛盾的记录（例如
50	// 先写负时间片再用同名字段写回合法值）就会被误认作完好。判定按 encoding/json
51	// 选择字段的方式归并名称：对记录、世界状态、规则、道路、角色与物品条目等
52	// 结构体对象，只要两个名称会被读取为同一个固定字段就算重复——含 Unicode
53	// 转义还原后的写法，以及只改大小写的写法（"Time" 与 "time"、"ID" 与
54	// "id"）都不能绕过；两个值相同、交换先后顺序、后一个值让世界合法或校验
55	// 和匹配都不豁免。名称到数值的携带上限对象解码到 map，其键是实际角色
56	// 标识而非固定字段，按还原后的精确名称比较，hero 与 HERO 是两个角色，不
57	// 合并也不误报。不同对象各自使用相同名称不受影响。
58	//
59	// 记录格式只支持 recordFormatVersion：格式编号缺失、为零、为负或为其他
60	// 正整数的记录按损坏处理，即使校验和匹配、世界状态合法、规则版本可被
61	// 调用方接受也不交付——目录能打开不代表每条记录都是当前功能理解的格式。
62	// 格式校验先于内容校验和：校验和载荷的布局本身由格式定义，未知格式的
63	// 记录无法解释其校验语义。格式问题与规则版本分别判断，格式错误一律报
64	// CorruptError，绝不报成 VersionRejectedError。
65	//
66	// 对完整世界状态的认可与 WorldFromState 重建世界保持一致：时间片为负的
67	// 记录属于损坏记录——内容校验和匹配只说明内容完整，规则版本被接受也不
68	// 能使负时间片合法；这样的记录不能被读回，也不能作为恢复或分支的来源。
69	func (a *Archive) loadAndVerifyLocked(id RecordID) (*envelope, error) {
70		env, err := loadRecord(recordPath(a.dir, id))
71		if err != nil {
72			if errors.Is(err, os.ErrNotExist) {
73				return nil, &NotFoundError{Record: id}
74			}
75			return nil, &CorruptError{Record: id, Reason: err.Error()}
76		}
77		if env.ID != id {
78			return nil, &CorruptError{Record: id, Reason: "记录标识与文件名不一致"}
79		}
80		if env.Format != recordFormatVersion {
81			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("不支持的记录格式版本: %d", env.Format)}
82		}
83		if got := computeChecksum(env); got != env.Checksum {
84			return nil, &CorruptError{Record: id, Reason: "内容校验和不匹配（可能已损坏或被改动）"}
85		}
86		// 父记录关系必须落到一个真实存在的记录上。
87		if env.Parent != "" {
88			if _, err := os.Stat(recordPath(a.dir, env.Parent)); err != nil {
89				if errors.Is(err, os.ErrNotExist) {
90					return nil, &CorruptError{Record: id, Reason: "父记录缺失: " + string(env.Parent)}
91				}
92				return nil, err
93			}
94		}
95		// 时间片为负的记录与 WorldFromState 的拒绝保持一致：即使校验和匹配、
96		// 其余状态合法，也按损坏处理，不自动把时间改成零。
97		if env.State.Time < 0 {
98			return nil, &CorruptError{Record: id, Reason: fmt.Sprintf("记录中的时间片为负: %d", env.State.Time)}
99		}
100		if err := validateInitialData(InitialData{
101			Seed:       env.State.Seed,
102			Rules:      env.State.Rules,
103			Characters: env.State.Characters,
104		}); err != nil {
105			return nil, &CorruptError{Record: id, Reason: "记录中的世界数据不合法: " + err.Error()}
106		}
107		return env, nil
108	}
109	
110	func versionAccepted(version string, accepted []string) bool {
111		for _, v := range accepted {
112			if v == version {
113				return true
114			}
115		}
116		return false
117	}
118	
119	func envToRecord(env *envelope) Record {
120		return Record{
121			ID:        env.ID,
122			Parent:    env.Parent,
123			SlotFirst: env.SlotFirst,
124			State:     cloneState(env.State),
125		}
126	}
127	
128	// Latest 读取槽当前最新记录。
129	//
130	// acceptedVersions 是调用方明确给出的可接受规则版本集合：记录完好但
131	// 版本不在集合内时返回 *VersionRejectedError；记录损坏（文本编码或
132	// Unicode 转义损坏、同一对象内名称重复、格式版本不受支持、校验和不符、
133	// 父记录缺失、无法解析、时间片为负）时返回 *CorruptError。文本损坏、
134	// 名称重复与格式问题都先于版本判断：即使版本不被接受，损坏的记录也报
135	// 损坏而不报版本拒绝。
136	// 读取不会改写存档。
137	func (a *Archive) Latest(slot string, acceptedVersions []string) (Record, error) {
138		if !validSlotName(slot) {
139			return Record{}, &NotFoundError{Slot: slot}
140		}
141		lock, err := acquireSharedLock(a.dir)
142		if err != nil {
143			return Record{}, err
144		}
145		defer lock.release()
146	
147		id, err := a.readLatestLocked(slot)
148		if err != nil {
149			return Record{}, err
150		}
151		env, err := a.loadAndVerifyLocked(id)
152		if err != nil {
153			if ce, ok := err.(*CorruptError); ok {
154				ce.Slot = slot
155			}
156			return Record{}, err
157		}
158		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
159			return Record{}, &VersionRejectedError{
160				Slot:     slot,
161				Record:   id,
162				Version:  env.State.Rules.Version,
163				Accepted: append([]string(nil), acceptedVersions...),
164			}
165		}
166		return envToRecord(env), nil
167	}
168	
169	// Record 按标识读取槽的一份历史记录（覆盖、升级或确认恢复之后，较早的
170	// 旧记录仍可按其标识读取）。
171	//
172	// 与 Latest 一样检查记录格式版本、内容校验和（含父记录关系）与规则版本，
173	// 且记录必须属于该槽的历史链。acceptedVersions 必须显式给出调用方可以
174	// 接受的规则版本：记录完好但版本不在集合内时返回 *VersionRejectedError。
175	// 读取不会切换槽当前记录，不会修补记录，也不会替换记录中的规则版本。
176	func (a *Archive) Record(slot string, id RecordID, acceptedVersions []string) (Record, error) {
177		if !validSlotName(slot) {
178			return Record{}, &NotFoundError{Slot: slot}
179		}
180		lock, err := acquireSharedLock(a.dir)
181		if err != nil {
182			return Record{}, err
183		}
184		defer lock.release()
185	
186		if err := a.assertInSlotHistoryLocked(slot, id); err != nil {
187			return Record{}, err
188		}
189		env, err := a.loadAndVerifyLocked(id)
190		if err != nil {
191			if ce, ok := err.(*CorruptError); ok {
192				ce.Slot = slot
193			}
194			return Record{}, err
195		}
196		if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
197			return Record{}, &VersionRejectedError{
198				Slot:     slot,
199				Record:   id,
200				Version:  env.State.Rules.Version,
201				Accepted: append([]string(nil), acceptedVersions...),
202			}
203		}
204		return envToRecord(env), nil
205	}
206	
207	// History 浏览槽已经保存生效的历史，返回每条记录的元信息（记录标识、
208	// 父标识、槽首标记、规则版本），供先浏览、再用 [Archive.Record] 按标识
209	// 读取完整世界。
210	//
211	// 次序按该槽“保存生效的先后”排列：最近一次成功保存的记录在最前，槽首
212	// 记录在末尾。它既不按记录里的世界时间片排序，也不按记录文件的修改时间
213	// 排序——确认恢复允许时间片回到较早来源的时刻，那次保存产生的新记录仍排
214	// 在最前，而原先已经生效的其他保存按原次序保留。
215	//
216	// 父标识表示“这条记录由哪一次保存承接而来”，与列表次序是两回事。槽首
217	// 标记不能统一解释成“父标识为空”：只有直接建立的槽首记录没有父记录；
218	// 分支槽的首条记录虽然标记为槽首，却以来源槽的那条记录为父记录。分支槽
219	// 只列分支自身保存生效的记录，不会因为分支首记录的父指向来源槽，就把
220	// 来源槽的历史补进列表。
221	//
222	// 列表只做完整性检查，不筛选规则版本：History 没有可接受版本参数，一份
223	// 记录只要确实保存生效且通过与 Record 一致的完整性检查——标识与文件一致、
224	// 文本编码合法、同一对象内名称不重复、记录格式受支持、内容校验和正确
225	// （含父记录关系）、世界状态合法、直接父记录文件存在——即使规则版本较旧或陌生也照常列出。因此“出现在列表里”
226	// 只说明记录完好，不保证调用方立即可用：用 Record 读取时仍必须显式给出
227	// 可接受版本集合，版本不被接受会得到 *VersionRejectedError，不能据此认为
228	// 历史列错了。
229	//
230	// 带历史索引的槽中，单条损坏、缺失或无法解析的记录只被略过，列表继续
231	// 返回其余合格记录，最新或某条中间记录出问题不会让整个浏览失败；但直接
232	// 父记录文件被删除的子记录因不满足父关系要求也被略过，而父文件仍在、
233	// 只是内容损坏时，不因此略过自身完好的子记录。旧版本写出的无历史索引槽
234	// 沿校验通过的父链在内存中重建，只列仍能确认归属本槽的记录，重建在损坏
235	// 处停止，不能承诺越过损坏处继续寻找更老的记录。
236	//
237	// 槽存在但没有任何合格记录时，返回成功的非 nil 空列表；槽不存在返回
238	// *NotFoundError，槽指针无法解析返回 *CorruptError，三者互不等同，不能把
239	// 不存在或损坏当成空列表。浏览只做只读遍历，不切换槽当前记录、不修补或
240	// 删除记录、不改写历史与世界规则。
241	func (a *Archive) History(slot string) ([]RecordInfo, error) {
242		if !validSlotName(slot) {
243			return nil, &NotFoundError{Slot: slot}
244		}
245		lock, err := acquireSharedLock(a.dir)
246		if err != nil {
247			return nil, err
248		}
249		defer lock.release()
250	
251		history, err := a.slotHistoryLocked(slot)
252		if err != nil {
253			return nil, err
254		}
255		infos := make([]RecordInfo, 0, len(history))
256		for _, id := range history {
257			// 与 Record 相同的完整性检查（不做规则版本取舍）：任何一条
258			// 记录损坏、缺失或无法解析都只略过它本身，不读其中的父标识或
259			// 槽首标记去扩大或缩小遍历范围，也不让整个列表失败。
260			env, verifyErr := a.loadAndVerifyLocked(id)
261			if verifyErr != nil {
262				continue
263			}
264			infos = append(infos, RecordInfo{
265				ID:        env.ID,
266				Parent:    env.Parent,
267				SlotFirst: env.SlotFirst,
268				Version:   env.State.Rules.Version,
269			})
270		}
271		return infos, nil
272	}
273	
274	// RecoverLatest 返回该槽“按保存生效次序最近的一份”内容校验通过且规则
275	// 版本可接受的已保存记录。
276	//
277	// 遍历次序完全来自槽指针维护的历史索引（最新在前），既不依据文件修改
278	// 时间，也不读取受损记录里的父标识或槽首标记：因此最新记录被删除、
279	// 截断成无法解析的内容，或连同若干中间记录一起损坏时，仍能越过它们
280	// 找到本槽更早的可用记录，而不会被引向别的槽或遮住更早的可用记录。遍历
281	// 次序与世界时间片的大小无关；时间片为负的记录属于损坏记录，同样被越过。
282	// 格式版本不受支持的记录（即使校验和匹配、状态合法）同样被越过，连续
283	// 多份未知格式记录也不会遮住其后格式受支持的完好记录。
284	//
285	// 分支槽只在分支自身已成功保存的记录中查找；即使分支首条记录损坏也不
286	// 越过分支边界，其他槽即使种子和规则相同也不会替代。版本不被接受的
287	// 记录一律跳过且不自动升级。只有记录文件写完且指针已更新（即保存完整
288	// 生效）的记录才在候选中：残留临时文件、写完但尚未完成保存的孤儿记录
289	// 不会被选中。
290	//
291	// 槽不存在返回 *NotFoundError；槽指针不可读返回 *CorruptError；槽中没有
292	// 任何版本可接受的完好记录时返回包装了 ErrUnrecoverable 的
293	// *UnrecoverableError，可用 errors.Is(err, ErrUnrecoverable) 判断。
294	// 恢复读取不会改写槽、指针、历史记录或规则，重复读取也不消耗历史。
295	func (a *Archive) RecoverLatest(slot string, acceptedVersions []string) (Record, error) {
296		if !validSlotName(slot) {
297			return Record{}, &NotFoundError{Slot: slot}
298		}
299		lock, err := acquireSharedLock(a.dir)
300		if err != nil {
301			return Record{}, err
302		}
303		defer lock.release()
304	
305		history, err := a.slotHistoryLocked(slot)
306		if err != nil {
307			return Record{}, err
308		}
309	
310		env, err := a.firstRecoverableLocked(history, acceptedVersions)
311		if err != nil {
312			var ue *UnrecoverableError
313			if errors.As(err, &ue) {
314				ue.Slot = slot
315			}
316			return Record{}, err
317		}
318		return envToRecord(env), nil
319	}
320	
321	// firstRecoverableLocked 在调用方已持锁的前提下，按给定的保存生效次序
322	// （最新在前）返回第一份“内容与父关系校验通过且规则版本可接受”的记录。
323	//
324	// 文件缺失、截断、文本编码损坏、同一对象内名称重复、格式版本不受支持、
325	// 校验和不符、记录标识不符、父关系异常、时间片为负或世界状态不自洽的
326	// 记录一律越过（不读其中的父标识或槽首标记）；
327	// 版本不被接受的记录也越过且不自动升级。次序完全由调用方给出（来自槽指针
328	// 历史索引或沿可信父链的重建），因此不会被引向别的槽。没有任何可用记录时
329	// 返回包装了 ErrUnrecoverable 的 *UnrecoverableError（Slot 字段由调用方
330	// 补全）。
331	func (a *Archive) firstRecoverableLocked(history []RecordID, acceptedVersions []string) (*envelope, error) {
332		var lastReason string
333		for _, id := range history {
334			env, verifyErr := a.loadAndVerifyLocked(id)
335			if verifyErr != nil {
336				lastReason = verifyErr.Error()
337				continue
338			}
339			if !versionAccepted(env.State.Rules.Version, acceptedVersions) {
340				lastReason = (&VersionRejectedError{
341					Record:  id,
342					Version: env.State.Rules.Version,
343				}).Error()
344				continue
345			}
346			return env, nil
347		}
348	
349		if lastReason == "" {
350			lastReason = "槽中没有任何可确认归属的历史记录"
351		}
352		return nil, &UnrecoverableError{Reason: lastReason}
353	}
