1	package world
2	
3	import (
4		"encoding/json"
5		"errors"
6		"os"
7		"reflect"
8		"strings"
9		"testing"
10	)
11	
12	// rewriteRecordText 把记录文件中的 from 原样替换为 to（to 可含无效 UTF-8
13	// 字节或不成对的 Unicode 代理项转义），并按替换字符补齐后的解析结果重算
14	// 内容校验和写回，模拟“损坏文本被替换字符补齐后仍通过校验和检查”的记录：
15	// 替换后的世界状态合法、校验和匹配，只有按原始字节检查文本编码才能发现。
16	func rewriteRecordText(t *testing.T, a *Archive, id RecordID, from, to string) {
17		t.Helper()
18		path := recordPath(a.dir, id)
19		raw, err := os.ReadFile(path)
20		if err != nil {
21			t.Fatal(err)
22		}
23		var env envelope
24		if err := json.Unmarshal(raw, &env); err != nil {
25			t.Fatal(err)
26		}
27		oldSum := env.Checksum
28		if !strings.Contains(string(raw), from) {
29			t.Fatalf("记录 %s 中找不到待替换文本 %q", id, from)
30		}
31		corrupted := strings.Replace(string(raw), from, to, 1)
32		// encoding/json 会把无效字节与不成对的代理项转义改写成替换字符，解析
33		// 仍然成功；按解析结果重算校验和，使损坏在校验和下被掩盖。
34		var cenv envelope
35		if err := json.Unmarshal([]byte(corrupted), &cenv); err != nil {
36			t.Fatalf("测试前提：损坏后的记录应仍可被 encoding/json 解析: %v", err)
37		}
38		corrupted = strings.Replace(corrupted, oldSum, computeChecksum(&cenv), 1)
39		if err := os.WriteFile(path, []byte(corrupted), 0o600); err != nil {
40			t.Fatal(err)
41		}
42	}
43	
44	// assertTextCorrupt 断言 err 是保留了被拒绝记录标识、且说明损坏类别
45	// （文本编码或 Unicode 转义）的 *CorruptError，而不是版本拒绝或其它错误。
46	func assertTextCorrupt(t *testing.T, err error, id RecordID, keyword string) {
47		t.Helper()
48		ce, ok := err.(*CorruptError)
49		if !ok {
50			t.Fatalf("应为 *CorruptError，得到 %T: %v", err, err)
51		}
52		if ce.Record != id {
53			t.Fatalf("CorruptError 应保留被拒绝的记录标识 %s，得到 %q", id, ce.Record)
54		}
55		if !strings.Contains(ce.Error(), keyword) {
56			t.Fatalf("错误应说明损坏类别 %q: %v", keyword, ce)
57		}
58		if errors.As(err, new(*VersionRejectedError)) {
59			t.Fatalf("文本损坏不应报成版本拒绝: %v", err)
60		}
61	}
62	
63	// TestLatestAndRecordInvalidUTF8Corrupt 记录文件中出现无效 UTF-8 字节时，
64	// 即使替换字符补齐后的世界状态合法、校验和匹配、规则版本也被接受，Latest
65	// 与 Record 都必须把整条记录视为损坏，返回保留记录标识并说明文本编码损坏
66	// 的 *CorruptError；读取保持只读，不修补这份记录。
67	func TestLatestAndRecordInvalidUTF8Corrupt(t *testing.T) {
68		a, _ := newTestArchive(t)
69		ids := saveN(t, a, "s", 1) // r1 r0
70		// 角色标识中的无效字节：替换后是合法的 "he�ro"，状态自洽、校验和匹配。
71		rewriteRecordText(t, a, ids[0], `"ID": "hero"`, "\"ID\": \"he\xffro\"")
72		before := recordFileBytes(t, a, ids[0])
73	
74		_, err := a.Latest("s", []string{"v1"})
75		assertTextCorrupt(t, err, ids[0], "UTF-8")
76	
77		_, err = a.Record("s", ids[0], []string{"v1"})
78		assertTextCorrupt(t, err, ids[0], "UTF-8")
79	
80		// 版本不被接受时同样报损坏，不报版本拒绝。
81		_, err = a.Latest("s", []string{"other"})
82		assertTextCorrupt(t, err, ids[0], "UTF-8")
83	
84		// 记录没有被悄悄修补或删除，槽指向不变。
85		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
86			t.Fatal("读取改写了文本损坏的记录")
87		}
88		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
89			t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
90		}
91	
92		// 本槽完好的历史记录不受影响，仍可正常读取。
93		if _, err := a.Record("s", ids[1], []string{"v1"}); err != nil {
94			t.Fatalf("完好的历史记录应可读: %v", err)
95		}
96	}
97	
98	// TestUnpairedSurrogateEscapeCorrupt 字符串值与对象键中不成对的 Unicode
99	// 代理项转义（高位未紧接合法低位、低位单独出现）都属于损坏：即使替换后的
100	// 状态合法、校验和匹配，也一律返回 *CorruptError。
101	func TestUnpairedSurrogateEscapeCorrupt(t *testing.T) {
102		cases := []struct {
103			name string
104			from string
105			to   string
106		}{
107			{"高位后接普通文字", `"ID": "hero"`, `"ID": "he\uD800ro"`},
108			{"高位在字符串末尾", `"ID": "hero"`, `"ID": "her\uD800"`},
109			{"高位后接非低位转义", `"ID": "hero"`, `"ID": "he\uD800Ao"`},
110			{"低位单独出现", `"ID": "hero"`, `"ID": "he\uDC00ro"`},
111			{"对象键中的高位代理项", `"hero": 5`, `"he\uDBFFAro": 5`},
112		}
113		for _, tc := range cases {
114			t.Run(tc.name, func(t *testing.T) {
115				a, _ := newTestArchive(t)
116				info := saveBase(t, a, "s")
117				rewriteRecordText(t, a, info.ID, tc.from, tc.to)
118				before := recordFileBytes(t, a, info.ID)
119	
120				_, err := a.Latest("s", []string{"v1"})
121				assertTextCorrupt(t, err, info.ID, "Unicode")
122	
123				_, err = a.Record("s", info.ID, []string{"v1"})
124				assertTextCorrupt(t, err, info.ID, "Unicode")
125	
126				// 版本不被接受时也报损坏。
127				_, err = a.Latest("s", []string{"other"})
128				assertTextCorrupt(t, err, info.ID, "Unicode")
129	
130				if got := recordFileBytes(t, a, info.ID); string(got) != string(before) {
131					t.Fatal("读取改写了转义损坏的记录")
132				}
133			})
134		}
135	}
136	
137	// TestHistorySkipsTextCorruptRecords 带历史索引的槽中，文本损坏的记录在
138	// 浏览时只被略过，其余完好记录仍按保存生效次序列出；恢复读取与恢复预览
139	// 选择本槽最近一份完整且版本可接受的记录，全部不可用时返回
140	// ErrUnrecoverable。浏览、读取与预览都不修补、删除或切换任何内容。
141	func TestHistorySkipsTextCorruptRecords(t *testing.T) {
142		a, _ := newTestArchive(t)
143		ids := saveN(t, a, "s", 2) // r2(time 2) r1(time 1) r0(time 0)
144		rewriteRecordText(t, a, ids[0], `"ID": "hero"`, `"ID": "he\uD800ro"`)
145		before := recordFileBytes(t, a, ids[0])
146	
147		// 浏览略过损坏的最新记录，其余按保存生效次序列出。
148		infos, err := a.History("s")
149		if err != nil {
150			t.Fatalf("History: %v", err)
151		}
152		if len(infos) != 2 || infos[0].ID != ids[1] || infos[1].ID != ids[2] {
153			t.Fatalf("损坏记录应被略过，其余按次序列出: %+v", infos)
154		}
155	
156		// 恢复读取与恢复预览选中最近一份完好且版本可接受的记录。
157		rec, err := a.RecoverLatest("s", []string{"v1"})
158		if err != nil {
159			t.Fatalf("RecoverLatest: %v", err)
160		}
161		if rec.ID != ids[1] || rec.State.Time != 1 {
162			t.Fatalf("应恢复 %s（时间片 1），得到 %s（时间片 %d）", ids[1], rec.ID, rec.State.Time)
163		}
164		pv, err := a.PreviewRecovery("s", []string{"v1"})
165		if err != nil {
166			t.Fatalf("PreviewRecovery: %v", err)
167		}
168		if pv.Current != ids[0] || pv.Source != ids[1] {
169			t.Fatalf("预览应为 current=%s source=%s，得到 current=%s source=%s",
170				ids[0], ids[1], pv.Current, pv.Source)
171		}
172	
173		// 全部记录都文本损坏时，恢复与预览返回 ErrUnrecoverable。
174		rewriteRecordText(t, a, ids[1], `"ID": "hero"`, `"ID": "he\uD800ro"`)
175		rewriteRecordText(t, a, ids[2], `"ID": "hero"`, `"ID": "he\uD800ro"`)
176		if _, err := a.RecoverLatest("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
177			t.Fatalf("全部损坏应不可恢复，得到 %T: %v", err, err)
178		}
179		if _, err := a.PreviewRecovery("s", []string{"v1"}); !errors.Is(err, ErrUnrecoverable) {
180			t.Fatalf("预览同样应不可恢复，得到 %T: %v", err, err)
181		}
182		if infos, err := a.History("s"); err != nil || len(infos) != 0 {
183			t.Fatalf("全部损坏时历史应为成功的空列表: %+v err=%v", infos, err)
184		}
185	
186		// 全程只读：受损文件未被修补或删除，槽当前指向不变。
187		if got := recordFileBytes(t, a, ids[0]); string(got) != string(before) {
188			t.Fatal("浏览/恢复改写了文本损坏的记录")
189		}
190		if p, err := a.readSlotPointerLocked("s"); err != nil || p.Latest != ids[0] {
191			t.Fatalf("槽指向不应改变: %+v err=%v", p, err)
192		}
193	}
194	
