// json.Unmarshal，这里不会再遇到语法问题。
func duplicatePointerField(data []byte) (string, bool) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil || tok != json.Delim('{') {
		return "", false
	}
	seen := map[string]bool{}
	atTop := true
	for atTop {
		tok, err := dec.Token()
		if err != nil {
			return "", false
		}
		if d, ok := tok.(json.Delim); ok && d == '}' {
			return "", false
		}
		key, ok := tok.(string)
		if !ok {
			return "", false
		}
		field := ""
		switch {
		case strings.EqualFold(key, "latest"):
			field = "latest"
		case strings.EqualFold(key, "history"):
			field = "history"
		}
		if field != "" {
			if seen[field] {
				return field, true
			}
			seen[field] = true
		}
		// 跳过该键对应的值（标量直接取下一个 token；数组或对象整体跳过），
		// 使下一轮仍停留在顶层键或右花括号上。
		if err := skipJSONValue(dec); err != nil {
			return "", false
		}
	}
	return "", false
}

// skipJSONValue 消费刚读入键之后的那一个 JSON 值：标量只需再读一个 token，
// 数组或对象按配对的分隔符整体跳过，不把其中内容当作顶层字段。
func skipJSONValue(dec *json.Decoder) error {
	tok, err := dec.Token()
	if err != nil {
		return err
	}
	d, ok := tok.(json.Delim)
	if !ok {
		return nil
	}
	var open, close byte
	switch d {
	case '{':
		open, close = '{', '}'
	case '[':
		open, close = '[', ']'
	default:
		return nil
	}
	depth := 1
	for depth > 0 {
		t, err := dec.Token()
		if err != nil {
			return err
		}
		if td, ok := t.(json.Delim); ok {
			switch byte(td) {
			case open:
				depth++
			case close:
				depth--
			}
		}
	}
	return nil
}

