	d, ok := tok.(json.Delim)
	if !ok {
		return nil
	}
	var open, close byte
	switch d {
	case '{':
		open, close = '{', '}'
	case '[':
		open, close = '[', ']'
	default:
		return nil
	}
	depth := 1
	for depth > 0 {
		t, err := dec.Token()
		if err != nil {
			return err
		}
		if td, ok := t.(json.Delim); ok {
			switch byte(td) {
			case open:
				depth++
			case close:
				depth--
			}
		}
	}
	return nil
}

