235		if dup, ok := duplicatePointerField(data); ok {
236			return slotPointer{}, &CorruptError{
237				Slot:   slot,
238				Reason: fmt.Sprintf("槽指针字段 %q 重复出现：同一对象内有两个名称会被读取为该字段，槽指针含义有歧义", dup),
239			}
240		}
241		if p.Latest == "" {
242			return slotPointer{}, &CorruptError{Slot: slot, Reason: "槽指针为空"}
243		}
244		return p, nil
245	}
