// encoding/json 对结构体字段的选择一致：因此 "latest" 与 "Latest"、
// "history" 与写作 Unicode 转义形式的同一名称（如 "latest"）都会
// 归并到同一字段，任一字段第二次出现即返回该字段标签。文本已通过
// json.Unmarshal，这里不会再遇到语法问题。
func duplicatePointerField(data []byte) (string, bool) {
	dec := json.NewDecoder(bytes.NewReader(data))
	dec.UseNumber()
	tok, err := dec.Token()
	if err != nil {
		return "", false
	}
	d, ok := tok.(json.Delim)
	if !ok || d != '{' {
		return "", false
	}
	seen := map[string]bool{}
	for {
		tok, err := dec.Token()
		if err != nil {
			return "", false
		}
		if d, ok := tok.(json.Delim); ok && d == '}' {
			return "", false
		}
		key, ok := tok.(string)
		if !ok {
			return "", false
		}
		field := ""
		switch {
		case strings.EqualFold(key, "latest"):
			field = "latest"
		case strings.EqualFold(key, "history"):
			field = "history"
		}
		if field != "" {
			if seen[field] {
				return field, true
			}
			seen[field] = true
		}
		// 跳过该键对应的值（标量直接取下一个 token；数组或对象整体跳过），
		// 使下一轮仍停留在顶层键或右花括号上。
		if err := skipJSONValue(dec); err != nil {
			return "", false
		}
	}
}

